def formula(t, dark=False):
    bg='#16212B' if dark else '#E9EEF1'
    return f'<p style="font-family:\'IBM Plex Mono\', monospace;font-size:30px;background:{bg};border-radius:12px;padding:24px 32px;line-height:1.5">{t}</p>'
def bars(rows, mx, unit='€', colors=None):
    out='<div style="display:flex;flex-direction:column;gap:14px;width:1664px">'
    for i,(lab,v,c) in enumerate(rows):
        w=int(1000*v/mx)
        out+=f'<div style="display:flex;align-items:center;gap:24px"><p style="width:420px;font-size:26px">{lab}</p><div style="width:{w}px;height:34px;background:{c};border-radius:6px"></div><p style="font-size:26px;font-weight:600">{str(v).replace(".",",")} {unit}</p></div>'
    return out+'</div>'
